(() => {
    const skipHomepageIntro = false;
    const mobileStaticHomepage = window.matchMedia("(max-width: 768px)").matches;
    window.bigbeeSkipHomepageIntro = skipHomepageIntro;

    if ("scrollRestoration" in history) {
        history.scrollRestoration = "manual";
    }

    const resetHomepageScroll = () => {
        document.documentElement.scrollTop = 0;
        if (document.body) document.body.scrollTop = 0;
        window.scrollTo(0, 0);
    };

    if (skipHomepageIntro && !mobileStaticHomepage) return;
    if (skipHomepageIntro && mobileStaticHomepage) {
        history.replaceState(history.state, "", window.location.pathname);
    }

    resetHomepageScroll();
    document.addEventListener("DOMContentLoaded", resetHomepageScroll, { once: true });
    window.addEventListener("pageshow", () => {
        resetHomepageScroll();
        requestAnimationFrame(resetHomepageScroll);
    });
})();
